2162	        view->w / 2 + (int32_t)lround(view->pan_dx),
2163	        view->h / 2 + (int32_t)lround(view->pan_dy));
2164	
2165	    if (view->follow_mode) {
2166	        const bool hidden = lv_obj_has_flag(view->arrow, LV_OBJ_FLAG_HIDDEN);
2167	
2168	        if (angle10 == view->last_arrow_angle10 && !hidden
2169	            && view->disp_arrow_angle10 == angle10) {
2170	            return;
2171	        }
2172	        view->last_arrow_angle10 = angle10;
2173	        lv_obj_align(view->arrow, LV_ALIGN_CENTER, 0, view->y_bias);
2174	        vmap_arrow_apply(view, angle10, !hidden);
2175	        lv_obj_remove_flag(view->arrow, LV_OBJ_FLAG_HIDDEN);
