2190	        if (!hidden && angle10 == view->last_arrow_angle10
2191	            && sx == lv_obj_get_x(view->arrow) + lv_obj_get_width(view->arrow) / 2
2192	            && sy == lv_obj_get_y(view->arrow) + lv_obj_get_height(view->arrow) / 2
