2293	static void pump_dirty_add(vmap_view_t * view, int32_t x1, int32_t y1,
2294	    int32_t x2, int32_t y2)
2295	{
2296	    uint8_t i;
2297	
2298	    if (!view || x1 >= x2 || y1 >= y2) {
2299	        return;
2300	    }
2301	
2302	    if (x1 < 0) {
2303	        x1 = 0;
2304	    }
2305	    if (y1 < 0) {
2306	        y1 = 0;
2307	    }
2308	    if (x2 > view->w) {
2309	        x2 = view->w;
2310	    }
2311	    if (y2 > view->h) {
2312	        y2 = view->h;
2313	    }
2314	    if (x1 >= x2 || y1 >= y2 || view->pump_dirty_n >= VMAP_RENDER_DIRTY_MAX) {
2315	        return;
2316	    }
2317	
2318	    i = view->pump_dirty_n;
2319	    view->pump_dirty_x1[i] = x1;
2320	    view->pump_dirty_y1[i] = y1;
2321	    view->pump_dirty_x2[i] = x2;
2322	    view->pump_dirty_y2[i] = y2;
2323	    view->pump_dirty_n++;
2324	}
