2326	static void pump_dirty_from_scroll(vmap_view_t * view, int32_t sx, int32_t sy)
2327	{
2328	    const int32_t pad = (int32_t)VMAP_RENDER_DIRTY_PAD;
2329	
2330	    view->pump_dirty_n = 0;
2331	    if (sx > 0) {
2332	        pump_dirty_add(view, view->w - sx - pad, 0, view->w, view->h);
2333	    } else if (sx < 0) {
2334	        pump_dirty_add(view, 0, 0, -sx + pad, view->h);
2335	    }
2336	    if (sy > 0) {
2337	        pump_dirty_add(view, 0, view->h - sy - pad, view->w, view->h);
2338	    } else if (sy < 0) {
2339	        pump_dirty_add(view, 0, 0, view->w, -sy + pad);
2340	    }
