2349	static bool pump_tile_dirty(const vmap_view_t * view, int32_t tx, int32_t ty)
2350	{
2351	    const int32_t tile_size = 256;
2352	    int32_t x1;
2353	    int32_t y1;
2354	    int32_t x2;
2355	    int32_t y2;
2356	    uint8_t i;
2357	
2358	    if (!view || view->pump_dirty_n == 0) {
2359	        return true;
2360	    }
2361	
2362	    x1 = (int32_t)lround((tx * tile_size - view->pump_cx) * view->scale
2363	        + view->w / 2.0);
2364	    y1 = (int32_t)lround((ty * tile_size - view->pump_cy) * view->scale
2365	        + view->h / 2.0);
2366	    x2 = (int32_t)lround(x1 + 256.0 * view->scale);
2367	    y2 = (int32_t)lround(y1 + 256.0 * view->scale);
2368	
2369	    for (i = 0; i < view->pump_dirty_n; i++) {
2370	        if (pump_rects_overlap(x1, y1, x2, y2,
2371	                view->pump_dirty_x1[i], view->pump_dirty_y1[i],
2372	                view->pump_dirty_x2[i], view->pump_dirty_y2[i])) {
2373	            return true;
2374	        }
2375	    }
2376	    return false;
2377	}
