2379	static bool pump_advance(vmap_view_t * view)
2380	{
2381	    view->pump_ty--;
2382	    if (view->pump_ty < view->pump_ty_min) {
2383	        view->pump_tx--;
2384	        view->pump_ty = view->pump_ty_max;
2385	    }
2386	    return view->pump_tx >= view->pump_tx_min;
2387	}
