2389	static void render_begin(vmap_view_t * view, bool reset_view, bool force_clear)
2390	{
2391	    vmap_canvas_t canvas;
2392	    const double origin_lon = reset_view ? view->lon : view->render_lon;
2393	    const double origin_lat = reset_view ? view->lat : view->render_lat;
2394	    int32_t sx;
2395	    int32_t sy;
2396	    bool scrolled = false;
2397	
2398	    /* 先置"帧在飞"再做任何 C 修改：期间的位置更新不能烘半成品。
2399	     * 两条路径（reset_view / keep-pan）都必须置位，否则泵不会推进。 */
2400	    view->pump_phase = 1;
2401	    view->pump_need_region = 1;
2402	
2403	    /* fopen/.vpk index belongs on the first pump tick, not GNSS/REC/set_view. */
2404	
2405	    vmap_perf_frame_begin();
2406	    VMAP_PERF_T0();
2407	    dvfs_map_busy(true);
2408	    view->pump_dirty_n = 0;
2409	    sx = (view->last_pan_px == INT32_MIN) ? (int32_t)lround(view->pan_dx)
2410	                                         : view->last_pan_px;
2411	    sy = (view->last_pan_py == INT32_MIN) ? (int32_t)lround(view->pan_dy)
2412	                                         : view->last_pan_py;
2413	
2414	    if (reset_view) {
2415	        /*
2416	         * A hidden page can jump much farther than the last on-screen pan.
2417	         * Derive the pixel migration from the two geographic origins instead
2418	         * of trusting last_pan_px.  Otherwise a 1 km jump with a 14 px old pan
2419	         * scrolls only 14 px, then marks the whole interior as the new origin.
2420	         */
2421	        if (!force_clear && view->render_rev > 0
2422	            && view->paint_zoom == view->zoom
2423	            && view->paint_scale == view->scale) {
2424	            int old_x = 0;
2425	            int old_y = 0;
2426	            int new_x = 0;
2427	            int new_y = 0;
2428	
2429	            vmap_latlong_to_pixel(view->render_lat, view->render_lon,
2430	                view->zoom, &old_x, &old_y);
2431	            vmap_latlong_to_pixel(origin_lat, origin_lon,
2432	                view->zoom, &new_x, &new_y);
2433	            sx = (int32_t)lround((new_x - old_x) * view->scale);
2434	            sy = (int32_t)lround((new_y - old_y) * view->scale);
2435	        }
2436	
2437	        bool can_scroll = !force_clear && view->render_rev > 0
2438	            && view->paint_zoom == view->zoom
2439	            && view->paint_scale == view->scale
2440	            && (sx != 0 || sy != 0)
2441	            && sx > -view->w && sx < view->w
2442	            && sy > -view->h && sy < view->h;
2443	
2444	        view->render_lon = origin_lon;
2445	        view->render_lat = origin_lat;
2446	        view_canvas(view, &canvas, false);
2447	        if (can_scroll) {
2448	            {
2449	                VMAP_PERF_T0S();
2450	                vmap_render_scroll(&canvas, sx, sy, vmap_style_bg565());
2451	                pump_dirty_from_scroll(view, sx, sy);
2452	                VMAP_PERF_T1S(scroll);
2453	            }
2454	            {
2455	                VMAP_PERF_T0S();
2456	                vmap_label_retained_scroll(&view->label_col, sx, sy,
2457	                    VMAP_RENDER_DIRTY_MAX, &view->pump_dirty_n,
2458	                    view->pump_dirty_x1, view->pump_dirty_y1,
2459	                    view->pump_dirty_x2, view->pump_dirty_y2);
2460	                VMAP_PERF_T1S(lscroll);
2461	            }
2462	            scrolled = true;
2463	            {
2464	                VMAP_PERF_T0S();
2465	                lv_obj_invalidate(view->canvas);
2466	                VMAP_PERF_T1S(inval);
2467	            }
2468	        } else {
2469	            VMAP_PERF_T0S();
2470	            vmap_render_clear(&canvas, vmap_style_bg565());
2471	            vmap_label_retained_reset(&view->label_col);
2472	            VMAP_PERF_T1S(scroll);  /* 清屏路径复用同一格 */
2473	        }
2474	
2475	        view->pan_dx = 0.0;
2476	        view->pan_dy = 0.0;
2477	        view->last_pan_px = INT32_MIN;
2478	        view->last_pan_py = INT32_MIN;
2479	        vmap_view_apply_canvas_pos(view, 0.0, 0.0);
2480	    } else {
2481	        /* keep-pan redraw repaints every base tile, erasing all baked labels. */
2482	        vmap_label_retained_reset(&view->label_col);
2483	    }
2484	
2485	    vmap_label_collector_reset(&view->label_col);
2486	    view->label_col.clip_n = 0;
2487	    vmap_label_collector_set_focus(&view->label_col,
2488	        view->w / 2 + (int32_t)lround(view->pan_dx),
2489	        view->h / 2 + (int32_t)lround(view->pan_dy));
2490	
2491	    vmap_latlong_to_pixel(origin_lat, origin_lon, view->zoom,
2492	        &view->pump_cx, &view->pump_cy);
2493	    /*
2494	     * ring=0（2026-10-27，对齐 X-TRACK 的 tile rect 语义）：
2495	     * 画布本身已经带了 margin 的 overscan，再往外加一圈瓦片只会选到**完全落在
2496	     * 画布之外**的瓦片 —— 近边不超过画布边，`vmap_render_draw_tile` 的像素写入
2497	     * 与 `label_pan_canvas_bounds()` 的标签收集都会把它们裁掉，却仍然要付要素
2498	     * 遍历（道路层还要按 class 扫 14 遍）和首帧的闪存读。
2499	     * 代价还落在节拍上：泵每 20 ms 只画 2 张，且从 (tx_max,ty_max) 开始扫，
2500	     * 多出来的一圈排在**可见区域之前**。实测几何（240x216 视口、margin 128、
2501	     * scale 1.69）是 16~20 张里只有 4~6 张与画布相交。
2502	     */
2503	    tile_range(view->pump_cx, view->pump_cy, view->w, view->h, view->scale, 0,
2504	        &view->pump_tx_min, &view->pump_ty_min,
2505	        &view->pump_tx_max, &view->pump_ty_max);
2506	    view->pump_tx = view->pump_tx_max;
2507	    view->pump_ty = view->pump_ty_max;
2508	
2509	    if (scrolled) {
2510	        syslog(LOG_INFO,
2511	            "[map] rebase scroll=%d,%d dirty=%u labels=%d z=%d",
2512	            (int)sx, (int)sy, (unsigned)view->pump_dirty_n,
2513	            (int)view->label_col.retained_count, view->zoom);
2514	    }
2515	    VMAP_PERF_T1(begin);
2516	}
