2518	static bool render_next_tile(vmap_view_t * view)
2519	{
2520	    const int32_t tile_size = 256;
2521	    const double scale = view->scale;
2522	    vmap_canvas_t canvas;
2523	    vmap_tile_t tile;
2524	    float base_x;
2525	    float base_y;
2526	    int32_t tx;
2527	    int32_t ty;
2528	    int32_t ix1;
2529	    int32_t iy1;
2530	    int32_t ix2;
2531	    int32_t iy2;
2532	
2533	    if (view->pump_need_region) {
2534	        VMAP_PERF_T0();
2535	        view->pump_need_region = 0;
2536	        if (view->cache) {
2537	            myvendor_watchdog_ui_beat();
2538	            myvendor_watchdog_busy_pump();
2539	            vmap_tile_cache_ensure_region(view->cache,
2540	                view->render_lon, view->render_lat);
2541	            myvendor_watchdog_ui_beat();
2542	        }
2543	        VMAP_PERF_T1(warm);
2544	        return true;
2545	    }
2546	
2547	    while (view->pump_tx >= view->pump_tx_min) {
2548	        tx = view->pump_tx;
2549	        ty = view->pump_ty;
2550	
2551	        if (!pump_tile_dirty(view, tx, ty)) {
2552	            VMAP_PERF_T0();
2553	            if (view->font
2554	                && vmap_tile_cache_cached(view->cache, view->zoom, (int)tx, (int)ty)
2555	                && vmap_tile_cache_get(view->cache, view->zoom, (int)tx, (int)ty,
2556	                    &tile)) {
2557	                base_x = (float)((tx * tile_size - view->pump_cx) * scale
2558	                    + view->w / 2.0);
2559	                base_y = (float)((ty * tile_size - view->pump_cy) * scale
2560	                    + view->h / 2.0);
2561	                vmap_label_collector_add_tile(&view->label_col, &tile,
2562	                    base_x, base_y, (float)scale);
2563	            }
2564	            VMAP_PERF_T1(meta);
