/**
 * @brief 只把 C 的脏区按当前 rot10 重转进 R（角度没变时的增量路径）。
 *
 * @details 变换与 `vmap_rot_labels_update()` 逐式相同：R 中心 = (rw/2, rh/2)，
 *          pivot 落在 R 中心，角度 view->rot10（0.1°，顺时针）。把 rot_dirty 的
 *          四角投到 R 坐标取 AABB，外扩 2 px（最近邻取整的余量）后作为 clip。
 *
 *          pivot 用**上一次烘焙时**的 pan（r_pan_*），不是当前 pan：R 的对象
 *          之后可能被 vmap_rot_track 平移过（buffer 内容不动、只有对象在挪），
 *          往 buffer 里写像素必须和 R 其余像素同处"烘焙时"的坐标系；用当前 pan
 *          会把补丁按对象位移错开（最多 r_margin 级）。
 *
 * @return true = R 已跟上脏区（或脏区投到 R 外、无需更新）；false = 原语拒绝/参数
 *         失败，调用方应回退整幅 `vmap_rot_full()`。
 */
static bool vmap_rot_area(vmap_view_t * view)
{
    int32_t pivot_x;
    int32_t pivot_y;
    int32_t x[4];
    int32_t y[4];
    int32_t x1;
    int32_t y1;
    int32_t x2;
    int32_t y2;
    int32_t i;
    double th;
    double c;
    double s;
    bool ok;

    if (view == NULL || view->rbuf == NULL || view->cbuf == NULL
        || view->rcanvas == NULL || vmap_rot_dirty_empty(view)) {
        return false;
    }

    /* 与 vmap_rot_full 同一套 pivot 算法，只是取烘焙时记下的 pan。 */
    pivot_x = view->margin + view->view_w / 2 + (int32_t)lround(view->r_pan_x);
    pivot_y = view->margin + view->view_h / 2 + (int32_t)lround(view->r_pan_y);
    if (pivot_x < 0 || pivot_y < 0 || pivot_x >= view->w || pivot_y >= view->h) {
        return false;   /* 烘焙时走了中心回退：变换对不上，整幅更稳 */
    }

    th = (double)view->rot10 * 0.1 * M_PI / 180.0;
    c = cos(th);
    s = sin(th);

    x[0] = view->rot_dirty_x0; y[0] = view->rot_dirty_y0;
    x[1] = view->rot_dirty_x1; y[1] = view->rot_dirty_y0;
    x[2] = view->rot_dirty_x0; y[2] = view->rot_dirty_y1;
    x[3] = view->rot_dirty_x1; y[3] = view->rot_dirty_y1;

    x1 = INT32_MAX; y1 = INT32_MAX;
    x2 = INT32_MIN; y2 = INT32_MIN;
    for (i = 0; i < 4; i++) {
        const double dx = (double)x[i] - (double)pivot_x;
        const double dy = (double)y[i] - (double)pivot_y;
        const int32_t rx = (int32_t)lround((double)view->rw / 2.0 + (c * dx - s * dy));
        const int32_t ry = (int32_t)lround((double)view->rh / 2.0 + (s * dx + c * dy));

        if (rx < x1) x1 = rx;
