/** @brief rot_dirty 是否为空（空集合约定：x0 > x1）。 */
static bool vmap_rot_dirty_empty(const vmap_view_t * view)
{
    return view->rot_dirty_x0 > view->rot_dirty_x1
        || view->rot_dirty_y0 > view->rot_dirty_y1;
}

/** @brief 清空 rot_dirty（x0 > x1 即空集合）。 */
static void vmap_rot_dirty_clear(vmap_view_t * view)
{
    view->rot_dirty_x0 = 1;
    view->rot_dirty_y0 = 1;
    view->rot_dirty_x1 = 0;
    view->rot_dirty_y1 = 0;
}

/** @brief 把画布坐标矩形并入 rot_dirty（调用方保证已 clamp 到画布内）。 */
static void vmap_rot_dirty_add(vmap_view_t * view, int32_t x1, int32_t y1,
    int32_t x2, int32_t y2)
{
    if (vmap_rot_dirty_empty(view)) {
        view->rot_dirty_x0 = x1;
        view->rot_dirty_y0 = y1;
        view->rot_dirty_x1 = x2;
        view->rot_dirty_y1 = y2;
        return;
    }
    if (x1 < view->rot_dirty_x0) {
        view->rot_dirty_x0 = x1;
    }
    if (y1 < view->rot_dirty_y0) {
        view->rot_dirty_y0 = y1;
    }
    if (x2 > view->rot_dirty_x1) {
        view->rot_dirty_x1 = x2;
    }
    if (y2 > view->rot_dirty_y1) {
        view->rot_dirty_y1 = y2;
    }
}
