/**
 * @brief 只把画布 C 的脏区按 rot10 重转进 R（角度没变时的增量路径）。
 *
 * @details 变换与 `vmap_rot_labels_update()` 逐式相同：R 中心 = (rw/2, rh/2)，
 *          pivot 落在 R 中心，角度 = rot10（0.1°，顺时针）。把 rot_dirty 四角
 *          投到 R 坐标取 AABB，外扩 2 px（最近邻取整的余量）后作为 clip。
 *
 *          pivot 取**上一次烘焙时**的 pan（r_pan_*），不是当前 pan：R 的对象
 *          之后可能被 `vmap_rot_track()` 平移过（buffer 内容不动、只有对象在挪），
 *          往 buffer 写像素必须和 R 其余像素同处"烘焙时"的坐标系；用当前 pan
 *          会把补丁按对象位移错开（可达 r_margin 级）。
 *
 * @return true = R 已跟上脏区（脏区整个投到 R 外也算，R 无需更新）；
 *         false = 参数/原语失败，调用方应回退整幅 `vmap_rot_full()`。
 */
static bool vmap_rot_area(vmap_view_t * view)
{
    int32_t pivot_x;
    int32_t pivot_y;
    int32_t cx[4];
    int32_t cy[4];
    int32_t x1;
    int32_t y1;
    int32_t x2;
    int32_t y2;
    int32_t i;
    uint32_t t0;
    uint32_t ms;
    double th;
    double c;
    double s;
    bool ok;

    if (view == NULL || view->rbuf == NULL || view->cbuf == NULL
        || view->rcanvas == NULL || vmap_rot_dirty_empty(view)) {
        return false;
    }

    /* pivot 与 vmap_rot_full 同算法，只是用烘焙时记下的 pan。 */
    pivot_x = view->margin + view->view_w / 2 + (int32_t)lround(view->r_pan_x);
    pivot_y = view->margin + view->view_h / 2 + (int32_t)lround(view->r_pan_y);
    if (pivot_x < 0 || pivot_y < 0 || pivot_x >= view->w || pivot_y >= view->h) {
        /* 烘焙时走的是"越界回退到画布中心"分支：这里复现不了，整幅更稳。 */
        return false;
    }

    th = (double)view->rot10 * 0.1 * M_PI / 180.0;
    c = cos(th);
    s = sin(th);

    cx[0] = view->rot_dirty_x0;
    cy[0] = view->rot_dirty_y0;
    cx[1] = view->rot_dirty_x1;
    cy[1] = view->rot_dirty_y0;
    cx[2] = view->rot_dirty_x0;
    cy[2] = view->rot_dirty_y1;
    cx[3] = view->rot_dirty_x1;
    cy[3] = view->rot_dirty_y1;

    x1 = INT32_MAX;
    y1 = INT32_MAX;
    x2 = INT32_MIN;
    y2 = INT32_MIN;
    for (i = 0; i < 4; i++) {
        const double dx = (double)cx[i] - (double)pivot_x;
        const double dy = (double)cy[i] - (double)pivot_y;
        const int32_t rx = (int32_t)lround((double)view->rw / 2.0
            + (c * dx - s * dy));
        const int32_t ry = (int32_t)lround((double)view->rh / 2.0
            + (s * dx + c * dy));

        if (rx < x1) {
            x1 = rx;
        }
        if (rx > x2) {
            x2 = rx;
        }
        if (ry < y1) {
            y1 = ry;
        }
        if (ry > y2) {
            y2 = ry;
        }
    }

    /* 最近邻取整 + 脏区右/下边是含端点像素：四周各留 2 px 再裁到 R。 */
    x1 -= 2;
    y1 -= 2;
    x2 += 2;
    y2 += 2;
    if (x1 < 0) {
        x1 = 0;
    }
    if (y1 < 0) {
        y1 = 0;
    }
    if (x2 > view->rw - 1) {
        x2 = view->rw - 1;
    }
    if (y2 > view->rh - 1) {
        y2 = view->rh - 1;
    }
    if (x1 > x2 || y1 > y2) {
        return true;            /* 脏区整个在 R 外：没有要更新的像素 */
    }

    t0 = lv_tick_get();
    ok = myvendor_epic_rotate_area(view->cbuf, view->stride, view->w, view->h,
        view->rbuf, view->rstride, view->rw, view->rh, view->rot10,
        pivot_x, pivot_y, view->rw / 2, view->rh / 2,
        x1, y1, x2 - x1 + 1, y2 - y1 + 1);
    ms = lv_tick_elaps(t0);
    if (!ok) {
        return false;
    }

    /* 只作废屏幕上这一块：R 对象的位置已含 -r_margin / y_bias / 跟车位移，
     * 用对象实际坐标换算，不在这里重算偏移。 */
    {
        lv_area_t coords;
        lv_area_t area;

        lv_obj_get_coords(view->rcanvas, &coords);
        area.x1 = coords.x1 + x1;
        area.y1 = coords.y1 + y1;
        area.x2 = coords.x1 + x2;
        area.y2 = coords.y1 + y2;
        lv_obj_invalidate_area(view->rcanvas, &area);
    }

    vmap_rot_dirty_clear(view);

    if (s_rot_area_pf.win == 0u) {
        s_rot_area_pf.win = lv_tick_get();
    }
    s_rot_area_pf.n++;
    s_rot_area_pf.sum_ms += ms;
    if (ms > s_rot_area_pf.max_ms) {
        s_rot_area_pf.max_ms = ms;
    }
    s_rot_area_pf.px += (uint32_t)(x2 - x1 + 1) * (uint32_t)(y2 - y1 + 1);
    if (lv_tick_elaps(s_rot_area_pf.win) >= 2000u) {
        if (s_rot_area_pf.n > 0u) {
            syslog(LOG_DEBUG, "[vrot] area n=%u avg=%ums max=%ums px=%u",
                (unsigned)s_rot_area_pf.n,
                (unsigned)(s_rot_area_pf.sum_ms / s_rot_area_pf.n),
                (unsigned)s_rot_area_pf.max_ms,
                (unsigned)s_rot_area_pf.px);
        }
        s_rot_area_pf.n = 0u;
        s_rot_area_pf.sum_ms = 0u;
        s_rot_area_pf.max_ms = 0u;
        s_rot_area_pf.px = 0u;
        s_rot_area_pf.win = lv_tick_get();
    }

    return true;
